            raise ValueError("max_requests must be non-negative")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be positive")

        self.max_requests = max_requests
        self.window_seconds = float(window_seconds)
        self._records: Dict[str, Deque[float]] = {}
        self._lock = threading.Lock()

    def _evict_expired(self, timestamps: Deque[float], current_time: float) -> None:
        threshold = current_time - self.window_seconds
        while timestamps and timestamps[0] <= threshold:
            timestamps.popleft()

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> Tuple[bool, float]:
        now = time.time() if timestamp is None else float(timestamp)

        with self._lock:
            if self.max_requests <= 0:
                return False, self.window_seconds

            if key not in self._records:
                self._records[key] = deque()

            records = self._records[key]
            self._evict_expired(records, now)

            if len(records) < self.max_requests:
                records.append(now)
                return True, 0.0

            oldest_request = records[0]
            retry_after = max(0.0, (oldest_request + self.window_seconds) - now)
            return False, retry_after

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        now = time.time() if timestamp is None else float(timestamp)

        with self._lock:
            if self.max_requests <= 0:
                return 0

            if key not in self._records:
                return self.max_requests

            records = self._records[key]
            self._evict_expired(records, now)
            return max(0, self.max_requests - len(records))
