            timestamp = time.time()

        with self._lock:
            cutoff = timestamp - self.window_seconds
            dq = self._requests.get(key)

            if dq:
                while dq and dq[0] <= cutoff:
                    dq.popleft()
                if not dq:
                    del self._requests[key]

            if key not in self._requests:
                dq = deque()
                self._requests[key] = dq

            if len(dq) < self.max_requests:
                if not dq or timestamp >= dq[-1]:
                    dq.append(timestamp)
                else:
                    idx = 0
                    while idx < len(dq) and dq[idx] <= timestamp:
                        idx += 1
                    dq.insert(idx, timestamp)
                return True, 0.0
            else:
                blocking_idx = len(dq) - self.max_requests
                retry_after = max(0.0, (dq[blocking_idx] + self.window_seconds) - timestamp)
                return False, retry_after

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        if timestamp is None:
            timestamp = time.time()

        with self._lock:
            dq = self._requests.get(key)
            if not dq:
