import asyncio
import itertools
from typing import Optional, Callable, Any


class AsyncWorkerPool:
    """An asynchronous worker pool using standard asyncio with priority queueing."""

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("Concurrency must be greater than 0")
        if max_queue_size <= 0:
            raise ValueError("Max queue size must be greater than 0")

        self.concurrency: int = concurrency
        self.max_queue_size: int = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: list[asyncio.Task] = []
        self._counter = itertools.count()
        self._is_started: bool = False
        self._is_shutting_down: bool = False

    async def start(self) -> None:
        """Spawns worker tasks to process enqueued jobs."""
        if self._is_started:
            return
        self._is_started = True
        for i in range(self.concurrency):
            worker_task = asyncio.create_task(
                self._worker(i), name=f"AsyncWorkerPool-worker-{i}"
            )
            self._workers.append(worker_task)

    async def submit(
        self, coro_func: Callable[..., Any], *args: Any, priority: int = 0, **kwargs: Any
    ) -> asyncio.Future:
        """
        Enqueues a coroutine function `coro_func(*args, **kwargs)` to be executed by pool workers.

        - Higher priority integers execute before lower priority integers.
        - Returns an asyncio.Future that resolves with the result (or exception) of coro_func.
        - Raises RuntimeError if pool is shutting down.
        """
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        fut: asyncio.Future = loop.create_future()
        count = next(self._counter)

        # Priority queue orders smallest primary key first.
        # Using `-priority` ensures higher numerical priority executes first.
        # `count` serves as a tie-breaker to preserve FIFO order for equal priorities
        # and prevents TypeError when comparing objects.
        item = (-priority, count, fut, coro_func, args, kwargs)

        await self._queue.put(item)
        return fut

    async def _worker(self, worker_id: int) -> None:
        while True:
            item = await self._queue.get()

            # Check for termination sentinel item (indicated by item[2] is None)
            if item[2] is None:
                self._queue.task_done()
                break

            _, _, fut, coro_func, args, kwargs = item

            # Skip execution if the user already cancelled the future before execution
            if fut.done() or fut.cancelled():
                self._queue.task_done()
                continue

            try:
                coro = coro_func(*args, **kwargs)
                task = asyncio.create_task(coro)
            except Exception as e:
                if not fut.done():
                    fut.set_exception(e)
                self._queue.task_done()
                continue

            # Forward cancellation of the returned future to the active inner task
            def _on_fut_done(f: asyncio.Future) -> None:
                if f.cancelled() and not task.done():
                    task.cancel()

            fut.add_done_callback(_on_fut_done)

            try:
                res = await task
                if not fut.done():
                    fut.set_result(res)
            except asyncio.CancelledError:
                if not fut.done():
                    fut.cancel()
            except Exception as e:
                if not fut.done():
                    fut.set_exception(e)
            finally:
                fut.remove_done_callback(_on_fut_done)
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """
        Shuts down the worker pool.

        - If drain=True, waits for all currently enqueued tasks to complete before stopping workers.
        - If drain=False, cancels all queued and currently executing tasks immediately.
        - Respects optional timeout seconds.
        """
        if self._is_shutting_down:
            return
        self._is_shutting_down = True

        # Prevent deadlock if shutdown(drain=True) is invoked without prior start()
        if not self._is_started:
            if drain and not self._queue.empty():
                await self.start()

        async def _do_shutdown() -> None:
            if drain and self._is_started:
                # Wait until all queued items are processed
                await self._queue.join()
                # Dispatch sentinel items to stop workers cleanly
                for _ in range(self.concurrency):
                    count = next(self._counter)
                    await self._queue.put((0, count, None, None, None, None))
                await asyncio.gather(*self._workers, return_exceptions=True)
            else:
                # Empty queue without executing remaining tasks and cancel their futures
                while not self._queue.empty():
                    try:
                        item = self._queue.get_nowait()
                        if item is not None and item[2] is not None:
                            fut = item[2]
                            if not fut.done():
                                fut.cancel()
                            self._queue.task_done()
                    except asyncio.QueueEmpty:
                        break

                # Forcefully cancel active worker tasks
                for w in self._workers:
                    w.cancel()
                if self._workers:
                    await asyncio.gather(*self._workers, return_exceptions=True)

        if timeout is not None:
            try:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            except asyncio.TimeoutError:
                # Forcefully cancel all workers if timeout is exceeded
                for w in self._workers:
                    w.cancel()
                if self._workers:
                    await asyncio.gather(*self._workers, return_exceptions=True)
        else:
            await _do_shutdown()
