import threading


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if max_connections <= 0:
            raise ValueError("max_connections must be greater than 0")
        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.Lock()
        self._next_id = 1
        self._closed = False
        self._all_connections = []
        self._available_connections = []

        for _ in range(max_connections):
            conn = self._create_connection()
            self._all_connections.append(conn)
            self._available_connections.append(conn)

    def _create_connection(self) -> dict:
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        with self._lock:
            if self._closed or not self._available_connections:
                raise RuntimeError("Pool exhausted")
            conn = self._available_connections.pop(0)
            if not conn.get("alive", False):
                new_conn = self._create_connection()
                if conn in self._all_connections:
                    idx = self._all_connections.index(conn)
                    self._all_connections[idx] = new_conn
                else:
                    self._all_connections.append(new_conn)
                conn = new_conn
            return conn

    def release(self, conn: dict) -> None:
        with self._lock:
            if self._closed or not isinstance(conn, dict):
                if isinstance(conn, dict):
                    conn["alive"] = False
                return
            if (
                conn not in self._available_connections
                and len(self._available_connections) < self.max_connections
            ):
                self._available_connections.append(conn)
                if conn not in self._all_connections:
                    self._all_connections.append(conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            if self._closed:
                return 0
            healed_count = 0
            for i in range(len(self._all_connections)):
                conn = self._all_connections[i]
                if not conn.get("alive", False):
                    new_conn = self._create_connection()
                    self._all_connections[i] = new_conn
                    if conn in self._available_connections:
                        idx = self._available_connections.index(conn)
                        self._available_connections[idx] = new_conn
                    else:
                        self._available_connections.append(new_conn)
                    healed_count += 1
            return healed_count

    def close_all(self) -> None:
        with self._lock:
            self._closed = True
            for conn in self._all_connections:
                conn["alive"] = False
            self._all_connections.clear()
            self._available_connections.clear()
