import time
from collections import OrderedDict
from threading import RLock
from typing import Optional, Any

class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.default_ttl_seconds = default_ttl_seconds
        self.cache = OrderedDict()
        self.lock = RLock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self.lock:
            expiry_duration = ttl if ttl is not None else self.default_ttl_seconds
            expiry_time = time.time() + expiry_duration

            if key in self.cache:
                self.cache[key] = (value, expiry_time)
                self.cache.move_to_end(key)
            else:
                if len(self.cache) >= self.capacity:
                    current_time = time.time()
                    expired_keys = [k for k, (_, exp) in self.cache.items() if exp <= current_time]
                    if expired_keys:
                        # Evict the oldest expired item (with the smallest expiry timestamp)
                        key_to_evict = min(expired_keys, key=lambda k: self.cache[k][1])
                        del self.cache[key_to_evict]
                    else:
                        # Evict the least recently used item (the first item in OrderedDict)
                        self.cache.popitem(last=False)
                self.cache[key] = (value, expiry_time)

    def get(self, key: str) -> Optional[Any]:
        with self.lock:
            if key not in self.cache:
                return None
            value, expiry_time = self.cache[key]
            if time.time() > expiry_time:
                del self.cache[key]
                return None
            self.cache.move_to_end(key)
            return value

    def delete(self, key: str) -> bool:
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self.lock:
            current_time = time.time()
            expired_keys = [k for k, (_, exp) in self.cache.items() if exp <= current_time]
            for k in expired_keys:
                del self.cache[k]
            return len(expired_keys)

    def size(self) -> int:
        with self.lock:
            current_time = time.time()
            return sum(1 for _, exp in self.cache.values() if exp > current_time)
