        self.window_seconds = window_seconds
        self.history: dict[str, deque[float]] = {}
        self.lock = threading.Lock()

    def _prune(self, key: str, current_time: float) -> None:
        cutoff = current_time - self.window_seconds
        queue = self.history.get(key)
        if queue:
            while queue and queue[0] <= cutoff:
                queue.popleft()
            if not queue:
                del self.history[key]

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        current_time = timestamp if timestamp is not None else time.time()
        with self.lock:
            self._prune(key, current_time)
            queue = self.history.get(key)
            if queue is None:
                queue = deque()
                self.history[key] = queue

            if len(queue) < self.max_requests:
                queue.append(current_time)
                return True, 0.0
            else:
                if not queue:
                    return False, self.window_seconds
                earliest = queue[0]
                retry_after = max(0.0, earliest + self.window_seconds - current_time)
                return False, retry_after

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
