from typing import Optional

class AsyncWorkerPool:
    """An asynchronous worker pool for executing coroutine functions with priority ordering."""

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        self._concurrency = concurrency
        self._max_queue_size = max_queue_size
        self._queue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers = []
        self._running = False
        self._shutting_down = False
        self._counter = 0
        self._active_futures = set()

    async def start(self) -> None:
        """Spawns worker tasks to process enqueued coroutine functions."""
        if self._running:
            return
        self._running = True
        self._shutting_down = False
        self._workers = [
            asyncio.create_task(self._worker())
            for _ in range(self._concurrency)
        ]

    async def submit(self, coro_func, *args, priority: int = 0, **kwargs) -> asyncio.Future:
        """
        Enqueues a coroutine function `coro_func(*args, **kwargs)` to be executed by the pool workers.
        Higher priority integer executes before lower priority integers.
        Returns an `asyncio.Future` that resolves with the result (or exception) of the coroutine function.
        """
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        fut = loop.create_future()

        # Use unique incrementing counter to avoid tuple comparison errors when priorities are equal
        self._counter += 1
        entry = (-priority, self._counter, (coro_func, args, kwargs, fut))

        try:
            await self._queue.put(entry)
        except asyncio.CancelledError:
            if not fut.done():
                fut.cancel()
            raise

        if self._shutting_down:
            if not fut.done():
                fut.set_exception(RuntimeError("Pool is shutting down"))
            raise RuntimeError("Pool is shutting down")

        return fut

    async def _worker(self):
        while True:
            try:
                priority, counter, item = await self._queue.get()
            except asyncio.CancelledError:
                # Worker task is cancelled, exit loop
                break

            coro_func, args, kwargs, fut = item

            if fut.done():
                self._queue.task_done()
                continue

            task = asyncio.create_task(coro_func(*args, **kwargs))
            self._active_futures.add(fut)

            # Setup cancellation callback to propagate client future cancellation to the running task
            def cancel_callback(f):
                if f.cancelled():
                    task.cancel()

            fut.add_done_callback(cancel_callback)

            try:
                try:
                    res = await asyncio.shield(task)
                    if not fut.done():
                        fut.set_result(res)
                except asyncio.CancelledError:
                    if task.cancelled():
                        if not fut.done():
                            fut.cancel()
                    else:
                        raise
                except Exception as e:
                    if not fut.done():
                        fut.set_exception(e)
            finally:
                fut.remove_done_callback(cancel_callback)
                self._active_futures.discard(fut)
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """
        Shuts down the worker pool.
        If `drain=True`, waits for all currently enqueued tasks to complete before stopping workers.
        If `drain=False`, cancels all queued and currently executing tasks immediately.
        Respects optional `timeout` seconds.
        """
        if self._shutting_down:
            return
        self._shutting_down = True

        try:
            if drain:
                if timeout is not None:
                    try:
                        await asyncio.wait_for(self._queue.join(), timeout=timeout)
                    except asyncio.TimeoutError:
                        pass
                else:
                    await self._queue.join()

            # Cancel all queued futures
            while not self._queue.empty():
                try:
                    priority, counter, item = self._queue.get_nowait()
                    coro_func, args, kwargs, fut = item
                    if not fut.done():
                        fut.cancel()
                    self._queue.task_done()
                except asyncio.QueueEmpty:
                    break

            # Cancel all active futures (which propagates cancellation to their tasks)
            for fut in list(self._active_futures):
                if not fut.done():
                    fut.cancel()

            # Cancel all workers
            for worker in self._workers:
                if not worker.done():
                    worker.cancel()

            # Wait for workers to finish
            if self._workers:
                if timeout is not None:
                    try:
                        await asyncio.wait_for(asyncio.gather(*self._workers, return_exceptions=True), timeout=timeout)
                    except asyncio.TimeoutError:
                        pass
                else:
                    await asyncio.gather(*self._workers, return_exceptions=True)

        finally:
            self._running = False
            self._workers.clear()
            self._active_futures.clear()
