import json
import hmac
import hashlib
import time

def verify_jwt(token: str, secret_key: str, allowed_algs: list[str] = ["HS256"]) -> dict:
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid JWT format")

    # Helper to handle proper Base64 URL decoding with dynamic padding
    def decode_b64url(s: str) -> bytes:
        rem = len(s) % 4
        if rem > 0:
            s += "=" * (4 - rem)
        try:
            return base64.urlsafe_b64decode(s)
        except Exception as e:
            raise ValueError("Invalid base64 encoding") from e

    try:
        header_raw = decode_b64url(parts[0])
        header = json.loads(header_raw)

        payload_raw = decode_b64url(parts[1])
        payload = json.loads(payload_raw)

        signature = decode_b64url(parts[2])
    except Exception as e:
        raise ValueError("Invalid JWT format or encoding") from e

    # Fix BUG 1: Validate algorithm against allowed_algs and explicitly reject "none"
    alg = header.get("alg")
    if not alg or alg == "none" or alg not in allowed_algs:
        raise ValueError("Algorithm not allowed")

    # Map standard HMAC algorithms to their hash functions dynamically
    if alg == "HS256":
        hash_func = hashlib.sha256
    elif alg == "HS384":
        hash_func = hashlib.sha384
    elif alg == "HS512":
        hash_func = hashlib.sha512
    else:
        raise ValueError("Unsupported algorithm")

    # Fix BUG 2: Correctly reject exact expiration timestamps (exp <= now)
    now = time.time()
    if "exp" in payload:
        exp = payload["exp"]
        if not isinstance(exp, (int, float)):
            raise ValueError("Invalid expiration format")
        if exp <= now:
            raise ValueError("Token expired")

    # Verify HMAC signature with the mapped hash algorithm
    signing_input = f"{parts[0]}.{parts[1]}".encode("utf-8")
    expected_sig = hmac.new(secret_key.encode("utf-8"), signing_input, hash_func).digest()

    if not hmac.compare_digest(signature, expected_sig):
        raise ValueError("Invalid signature")

    return payload
```

### Key Security Improvements:
1. **Strict Algorithm Checks:** Excluded `"none"` and verified that the algorithm in the header strictly matches one of the entries in `allowed_algs`. Supported HMAC algorithms (`HS256`, `HS384`, `HS512`) are resolved dynamically to prevent algorithm confusion attacks.
2. **Correct Expiration Bound:** Changed the condition `payload["exp"] < now` to `payload["exp"] <= now` to correctly expire tokens whose lifetime has elapsed to the exact second.
3. **Robust Base64url Decoding:** Implemented dynamic padding calculation (`len(s) % 4`) to correctly pad base64url inputs lacking standard padding characters (`=`).

