class CircularDependencyError(Exception):
    pass

class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        in_degree = {task: 0 for task in all_tasks}
        graph = {task: [] for task in all_tasks}

        for task, deps in dependencies.items():
            # Use set(deps) to handle duplicate dependencies gracefully
            for dep in set(deps):
                graph[dep].append(task)
                in_degree[task] += 1

        stages = []
        while True:
            # Find all tasks with no remaining dependencies
            zero_degree = [t for t, deg in in_degree.items() if deg == 0]

            if not zero_degree:
                break

            # Sort the tasks in the current stage alphabetically
            zero_degree.sort()
            stages.append(zero_degree)

            # Process these tasks: mark them as resolved and update their dependents
            for task in zero_degree:
                in_degree[task] = -1
                for dependent in graph[task]:
                    in_degree[dependent] -= 1

        # If any task still has unresolved dependencies, there must be a cycle
        if any(deg > 0 for deg in in_degree.values()):
            raise CircularDependencyError("Circular dependency detected.")

        return stages
