import time
import threading
from collections import deque
from typing import Optional

class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests <= 0:
            raise ValueError("max_requests must be greater than 0")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be greater than 0")

        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.requests = {}
        self.lock = threading.Lock()

    def _cleanup(self, key: str, current_time: float) -> None:
        """Removes timestamps that are outside the current sliding window."""
        if key not in self.requests:
            return

        q = self.requests[key]
        window_start = current_time - self.window_seconds

        # Remove requests that are older than or equal to the window start
        while q and q[0] <= window_start:
            q.popleft()

        # Clean up empty deques to save memory
        if not q:
            del self.requests[key]

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup(key, timestamp)

            q = self.requests.get(key)
            if q is None:
                q = deque()
                self.requests[key] = q

            if len(q) < self.max_requests:
                q.append(timestamp)
                return True, 0.0
            else:
                # The earliest request in the window is at q[0].
                # It will expire at q[0] + self.window_seconds.
                retry_after = (q[0] + self.window_seconds) - timestamp
                return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup(key, timestamp)
            q = self.requests.get(key)
            if q is None:
                return self.max_requests
            return self.max_requests - len(q)
